//--|🠊 Skeleton.scss 🠈|--\\
//--|🠋 Designs 🠋|--\\
@use './Mixins.scss' as Mixins;
@use './Palettes.scss' as Palettes;
@use './Transition.scss' as Transition;

body {
  div[class*='body'] {
    > * {
      height: 100svh;
      display: inherit; //--|🠈 display: grid; 🠈|--\\
      //--|🠊 All direct children inherit the parent grid coordinates 🠈|--\\
      grid-area: 1 / 1 / 6 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      section[class*='foreground'],
      figure[class*='midground'],
      div[class*='background'] {
        &[class*='foreground'] {
          z-index: 2;
          header[class*='default'] {
            z-index: 1;
            grid-area: 1 / 1 / 3 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          nav[class*='header'],
          nav[class*='footer'] {
            z-index: 0;
            height: 100svh;
            grid-area: 1 / 1 / 6 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          footer[class*='default'] {
            z-index: 1;
            grid-area: 4 / 1 / 6 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
        }
        &[class*='midground'] {
          z-index: 1;
        }
        &[class*='background'] {
          z-index: 0;
        }
      }
      //--|🠋 Desktop (Landscape) 🠋|--\\
      @media screen and (orientation: landscape) {
        @include Mixins.landscape-grid();
      }
      //--|🠋 Mobile (Portrait) 🠋|--\\
      @media screen and (orientation: portrait) {
        @include Mixins.portrait-grid();
      }
    }

    //--|🠊 display: grid; 🠈|--\\
    //--|🠋 Desktop (Landscape) 🠋|--\\
    @media screen and (orientation: landscape) {
      @include Mixins.landscape-grid;
    }
    //--|🠋 Mobile (Portrait) 🠋|--\\
    @media screen and (orientation: portrait) {
      @include Mixins.portrait-grid;
    }

    @extend %position;
    @extend %colouring;
    @extend %transition;
  }
  %position {
    main[class*='main'] {
      z-index: 0;
    }
    header[class*='header'],
    footer[class*='footer'] {
      figure {
        section[class*='default'] {
          width: 100vw;
          height: 100svh;
          flex: 0 0 100vw;
          min-width: 100vw;
        }
      }
    }

    section[class*='overlay'] {
      z-index: 10;
    }
    aside[class*='bar'] {
      &[class*='leftbar'] {
        z-index: 5;
      }
      &[class*='rightbar'] {
        z-index: 4;
      }
    }

    //--|===|--\\
    @media screen and (orientation: landscape) {
      header[class*='header'] {
        z-index: 6;
      }
      footer[class*='footer'] {
        z-index: 9;
      }
    }
    @media screen and (orientation: portrait) {
      header[class*='header'] {
        z-index: 9;
      }
      footer[class*='footer'] {
        z-index: 6;
      }
    }
  }
  %colouring {
    @at-root body[class*='meridiem'] {
      &::before {
        inset: 0;
        content: '';
        position: fixed;
        animation: overlay-fade 1.5s ease-in-out 3s both;
        @keyframes overlay-fade {
          from {
            opacity: 1;
          }
          to {
            opacity: 0;
          }
        }
      }
      //--|===|--\\
      &[class*='ante'] {
        background: Palettes.$indexLand-lightMode;
        &::before {
          background: white;
        }
      }
      &[class*='post'] {
        background: Palettes.$indexLand-darkMode;
        &::before {
          background: black;
        }
      }
    }
  }
  %transition {
    //--|🠊 Desktop 🠈|--\\
    @include Transition.header-transition();
    @include Transition.main-transition();
    @include Transition.footer-transition();
    //--|===|--\\
    @include Transition.overlay-transition();
    @include Transition.body-transition();
    @include Transition.sidebar-transition();
  }

  //--|===|--\\
  div[id='landing-body'] {
    //--|🠋 Desktop (Landscape) 🠋|--\\
    @media screen and (orientation: landscape) {
      //--|🟧| Landing |🟧|--\\
      @include Mixins.landscape-grid;
    }
    //--|🠋 Mobile (Portrait) 🠋|--\\
    @media screen and (orientation: portrait) {
      //--|🟧| Landing |🟧|--\\
      @include Mixins.portrait-grid;
    }
  }
  div[id='overtime-body'] {
    //--|🠋 Desktop (Landscape) 🠋|--\\
    @media screen and (orientation: landscape) {
      //--|🟩| Overtime |🟩|--\\
      @include Mixins.landscape-grid;
    }
    //--|🠋 Mobile (Portrait) 🠋|--\\
    @media screen and (orientation: portrait) {
      //--|🟩| Overtime |🟩|--\\
      @include Mixins.portrait-grid;
    }
  }
  div[id='ticketing-body'] {
    //--|🠋 Desktop (Landscape) 🠋|--\\
    @media screen and (orientation: landscape) {
      //--|🟦| Ticketing |🟦|--\\
      @include Mixins.landscape-grid;
    }
    //--|🠋 Mobile (Portrait) 🠋|--\\
    @media screen and (orientation: portrait) {
      //--|🟦| Ticketing |🟦|--\\
      @include Mixins.portrait-grid;
    }
  }
  div[id='hyperlink-body'] {
    //--|🠋 Desktop (Landscape) 🠋|--\\
    @media screen and (orientation: landscape) {
      //--|🟥| Hyperlink |🟥|--\\
      @include Mixins.landscape-grid;
    }
    //--|🠋 Mobile (Portrait) 🠋|--\\
    @media screen and (orientation: portrait) {
      //--|🟥| Hyperlink |🟥|--\\
      @include Mixins.portrait-grid;
    }
  }
  div[id='components-body'] {
    //--|🟨|--\\
    main[id*='components'] {
      aside[class*='form'],
      aside[class*='menu'],
      aside[class*='time'],
      aside[class*='table'],
      aside[class*='aside'],
      aside[class*='label'],
      aside[class*='button'],
      aside[class*='figure'],
      aside[class*='article'],
      aside[class*='section'],
      aside[class*='division'],
      aside[class*='navigation'] {
        width: 100vw;
        height: 100svh;
        flex: 0 0 100vw;
        min-width: 100vw;
      }
      //--|🠋 Desktop (Landscape) 🠋|--\\
      @media screen and (orientation: landscape) {
        //--|🟨| Archive |🟨|--\\
        @include Mixins.landscape-grid;
        aside[class*='time'],
        aside[class*='table'],
        aside[class*='figure'],
        aside[class*='article'],
        aside[class*='division'],
        aside[class*='navigation'] {
          @include Mixins.landscape-grid;
        }
        //--|===|--\\
        aside[class*='label'],
        aside[class*='button'] {
          @include Mixins.layering-position;
        }
      }
      //--|🠋 Mobile (Portrait) 🠋|--\\
      @media screen and (orientation: portrait) {
        //--|🟨| Archive |🟨|--\\
        @include Mixins.portrait-grid;
        aside[class*='time'],
        aside[class*='table'],
        aside[class*='figure'],
        aside[class*='article'],
        aside[class*='division'],
        aside[class*='navigation'] {
          @include Mixins.portrait-grid;
        }
        //--|===|--\\
        aside[class*='label'],
        aside[class*='button'] {
          @include Mixins.layering-position;
        }
      }
    }
  }
}
