//--|🠊 textarea/pipeline/Label_tint.scss 🠈|--\\
@use 'sass:color' as color;
@use '../../../../styles/Palettes.scss' as Palettes;

@mixin textarea-colors {
  //--|🠋 Global (Tint) 🠋|--\\
  $tint-fade: cubic-bezier(0.2, 0.8, 0.2, 1);
  @include mon-tint();
  @include red-tint();
  @include gre-tint();
  @include blu-tint();
  @include pur-tint();
  @include ora-tint();
  @include pin-tint();
  @include yel-tint();
  @include bro-tint();
  @include tur-tint();
  //--|🠋 Clarity 🠋|--\\
  //--|🠊 AI Code: Review Please 2026-10-30 🠈|--\\
  &[class*='_luc_'] {
    opacity: 1; //--|🠈 AI Code: Review Please 2026-10-30 · ⟨lucid⟩: solid, like <LabelSelection> 🠈|--\\
  }
  &[class*='_opa_'] {
    opacity: 1; //--|🠈 AI Code: Review Please 2026-10-30 · ⟨opaque⟩: see-through with a frame, set below and in *-tint 🠈|--\\
  }
  //--|🠋 Crossfade Layers 🠋|--\\
  /*--|🠋
    Why: A browser can't fade one gradient into another, it snaps.
    It can fade opacity. How: ::before holds the resting gradient,
    ::after the flipped one (Set in *-tint). On hover or focus ::before
    fades out while ::after fades in, so the gradients blend, like <Button>.
    Note: An <input> or <textarea> can't hold ::before or ::after, so the <label> carries
    both layers and the field stays see-through on top of them. [class='event'] is either one.
  🠉|--*/
  isolation: isolate; //--|🠈 Keeps the z-index: -1 layers above the parent, behind the field 🠈|--\\
  &::before,
  &::after {
    content: '';
    inset: 0;
    z-index: -1;
    position: absolute;
    pointer-events: none;
    border-radius: inherit; //--|🠈 Follows the size steps 🠈|--\\
  }
  &::before {
    transition: opacity 750ms $tint-fade;
  }
  &::after {
    opacity: 0;
    transition: opacity 750ms $tint-fade;
  }
  [class='event'] {
    background: none;
    transition:
      color 500ms $tint-fade,
      box-shadow 750ms $tint-fade, //--|🠈 The frame fades with the layers 🠈|--\\
      text-shadow 500ms $tint-fade;
    &::placeholder {
      transition: color 500ms $tint-fade;
    }
  }
  &:hover,
  &:has(:focus-visible) {
    //--|🠊 Flips on hover like <Button> and on keyboard focus, so it stays flipped while you type and reverts after a mouse click 🠈|--\\
    &::before {
      opacity: 0;
    }
    &::after {
      opacity: 1;
    }
  }
  &[class*='_opa_'] {
    //--|🠊 AI Code: Review Please 2026-10-30 · ⟨opaque⟩ like {select}: the layers drop to a quarter and lose the bevel, the frame is set in *-tint 🠈|--\\
    &::before {
      opacity: 0.25; //--|🠈 See-through, the page shows behind the text 🠈|--\\
      box-shadow: none;
    }
    &::after {
      box-shadow: none;
    }
    &:hover,
    &:has(:focus-visible) {
      &::before {
        opacity: 0;
      }
      &::after {
        opacity: 0.25;
      }
    }
  }
}
