  $neoLig: color.mix(Palettes.$gray-neon, Palettes.$gray-light, $weight: 70%);

  //--|🠊 Dark Shade: Fades into the Light Shade 🠈|--\\
  &[class*='dar_mon'] {
    &::before {
      background: linear-gradient(180deg, rgba(Palettes.$gray-neon, 0.06) 0%, rgba(Palettes.$gray-neon, 0) 45%, rgba(#000, 0.3) 100%), $darMed;
      box-shadow: //--|🠈 Bevel from <Button>'s div.back, no outer ring 🠈|--\\
        inset 0 1px 0 rgba(Palettes.$gray-neon, 0.09),
        inset 0 -1px 0 rgba(#000, 0.35),
        inset 0 0 0 1px rgba(Palettes.$gray-medium, 0.18);
    }
    &::after {
      background: linear-gradient(180deg, rgba(#fff, 0.18) 0%, rgba(#fff, 0) 42%, rgba(#000, 0.2) 100%), $ligMed;
      box-shadow: //--|🠈 Bevel from <Button>'s div.back, no outer ring 🠈|--\\
        inset 0 1px 0 rgba(#fff, 0.22),
        inset 0 -1px 0 rgba(#000, 0.25),
        inset 0 0 0 1px rgba(#000, 0.1);
    }
    [class='event'] {
      color: $neoLig; //--|🠈 Light text on a dark track 🠈|--\\
      text-shadow: //--|🠈 A thin dark outline in em, so it scales with the font like <Button> 🠈|--\\
        0 0 0.04em $blaDar,
        0 0 0.25em rgba($blaDar, 0.6);
      &::placeholder {
        color: $neoLig; //--|🠈 Same colour as the text, only fainter 🠈|--\\
        opacity: 0.75; //--|🠈 Same strength as the <Form> placeholders 🠈|--\\
      }
    }
    &:hover,
    &:has(:focus-visible) {
      [class='event'] {
        color: $blaDar; //--|🠈 Dark text on a light track 🠈|--\\
