    }
  }
  //--|🠊 Light Shade: Fades into the Dark Shade 🠈|--\\
  &[class*='lig_tur'] {
    &::before {
      background: linear-gradient(180deg, rgba(#fff, 0.18) 0%, rgba(#fff, 0) 42%, rgba(#000, 0.2) 100%), $ligMed;
      box-shadow: //--|🠈 Bevel from <Button>'s div.back, no outer ring 🠈|--\\
        inset 0 1px 0 rgba(#fff, 0.22),
        inset 0 -1px 0 rgba(#000, 0.25),
        inset 0 0 0 1px rgba(#000, 0.1);
    }
    &::after {
      background: linear-gradient(180deg, rgba(Palettes.$turquoise-neon, 0.06) 0%, rgba(Palettes.$turquoise-neon, 0) 45%, rgba(#000, 0.3) 100%), $darMed;
      box-shadow: //--|🠈 Bevel from <Button>'s div.back, no outer ring 🠈|--\\
        inset 0 1px 0 rgba(Palettes.$turquoise-neon, 0.09),
        inset 0 -1px 0 rgba(#000, 0.35),
        inset 0 0 0 1px rgba(Palettes.$turquoise-medium, 0.18);
    }
    [class='event'] {
      color: $blaDar; //--|🠈 Dark text on a light track 🠈|--\\
      text-shadow: //--|🠈 A thin light outline in em, so it scales with the font like <Button> 🠈|--\\
        0 0 0.04em $neoLig,
        0 0 0.25em rgba($neoLig, 0.6);
      &::placeholder {
        color: $blaDar; //--|🠈 Same colour as the text, only fainter 🠈|--\\
        opacity: 0.75; //--|🠈 Same strength as the <Form> placeholders 🠈|--\\
      }
    }
    &:hover,
    &:has(:focus-visible) {
      [class='event'] {
        color: $neoLig; //--|🠈 Light text on a dark track 🠈|--\\
        text-shadow: //--|🠈 A thin dark outline in em, so it scales with the font like <Button> 🠈|--\\
          0 0 0.04em $blaDar,
          0 0 0.25em rgba($blaDar, 0.6);
        &::placeholder {
          color: $neoLig; //--|🠈 Same colour as the text, only fainter 🠈|--\\
          opacity: 0.75; //--|🠈 Same strength as the <Form> placeholders 🠈|--\\
        }
      }
    }
    &[class*='_opa_'] {
      //--|🠊 AI Code: Review Please 2026-10-30 · ⟨opaque⟩: the {select} frame 🠈|--\\
      [class='event'] {
        box-shadow: //--|🠈 AI Code: Review Please 2026-10-30 · A light outline over a medium inset glow, like <LabelSwitching> 🠈|--\\
          inset 0 0 0 2px $neoLig,
          inset 0 0 0.5em Palettes.$turquoise-medium;
        text-shadow: //--|🠈 AI Code: Review Please 2026-10-30 · A heavier light halo, so the dark text reads on any background 🠈|--\\
          0 0 0.06em $neoLig,
          0 0 0.12em $neoLig,
          0 0 0.3em rgba($neoLig, 0.8);
      }
      &:hover,
      &:has(:focus-visible) {
        [class='event'] {
          box-shadow: //--|🠈 A dark outline + an inset drop shadow, so the light text stands out 🠈|--\\
            inset 0 0 0 2px $blaDar,
            inset 0 0.125em 0.25em $blaDar;
          text-shadow: //--|🠈 AI Code: Review Please 2026-10-30 · A heavier dark halo, so the light text reads on any background 🠈|--\\
            0 0 0.06em $blaDar,
            0 0 0.12em $blaDar,
            0 0 0.3em rgba($blaDar, 0.8);
        }
      }
    }
  }
