@mixin desktop-size {
  //--|🠋 Desktop (Size) 🠋|--\\
  div[class='text'] {
    h1 {
      font-size: 40px;
      font-weight: 800;
    }
    h2 {
      font-size: 32px;
      font-weight: 775;
    }
    h3 {
      font-size: 28px;
      font-weight: 750;
    }
    h4 {
      font-size: 24px;
      font-weight: 725;
    }
    h5 {
      font-size: 20px;
      font-weight: 700;
    }
    h6 {
      font-size: 16px;
      font-weight: 675;
    }
    p {
      font-size: 14px;
      font-weight: 650;
    }

    max-width: 32rem;
  }
  div[class='icon'] {
    img {
      width: 100%;
      height: 100%;
      object-fit: contain; //--|🠈 .png & .jpg keep their proportions 🠈|--\\
      //--|🠊 Frame the Icon Mask 🠈|--\\
      mask-mode: alpha; //--|🠈 PNG/SVG alpha masking 🠈|--\\
      mask-size: contain; //--|🠈 Fit icon inside box 🠈|--\\
      -webkit-mask-size: contain;

      mask-repeat: no-repeat; //--|🠈 Stop tiling bleed 🠈|--\\
      -webkit-mask-repeat: no-repeat;

      mask-position: center; //--|🠈 Center icon 🠈|--\\
      -webkit-mask-position: center;
    }
  }
  @media screen and (max-height: 768px) {
    div[class='text'] {
      max-width: 22rem;
      h1 {
        font-size: 32px;
      }
      h2 {
        font-size: 28px;
      }
      h3 {
        font-size: 24px;
      }
      h4 {
        font-size: 20px;
      }
      h5 {
        font-size: 16px;
      }
      h6 {
        font-size: 14px;
      }
      p {
        font-size: 12px;
      }
    }
  }
  @media screen and (max-height: 480px) {
    div[class='text'] {
      max-width: 14rem;
      h1 {
        font-size: 24px;
      }
      h2 {
        font-size: 20px;
      }
      h3 {
        font-size: 16px;
      }
      h4 {
        font-size: 16px;
      }
      h5 {
        font-size: 14px;
      }
      h6 {
        font-size: 12px;
      }
      p {
        font-size: 10px;
      }
    }
  }
  @media screen and (max-height: 360px) {
    div[class='text'] {
      max-width: 10rem;
      h1 {
        font-size: 16px;
      }
      h2 {
        font-size: 14px;
      }
      h3 {
        font-size: 12px;
      }
      h4 {
        font-size: 12px;
      }
      h5 {
        font-size: 10px;
      }
      h6 {
        font-size: 10px;
      }
      p {
        font-size: 8px;
      }
    }
  }
}
