//--|🠊 default/pipeline/Button_grid.scss 🠈|--\\
@mixin default-gridbox {
  //--|🠋 Global (Grid) 🠋|--\\
  width: 100%;
  height: 100%;
  display: grid;
  //--|🠊 Placement: Global, so [MobilePortrait] & [TabletSquaring] get it too (Lost in 3adc1ea1) 🠈|--\\
  &[class*='_top_'] {
    div[class='text'],
    div[class='back'] {
      grid-area: 2 / 2 / 3 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
    div[class='icon'] {
      grid-area: 3 / 3 / 4 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
  }
  &[class*='_bot_'] {
    div[class='text'],
    div[class='back'] {
      grid-area: 3 / 2 / 4 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
    div[class='icon'] {
      grid-area: 2 / 3 / 3 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
  }
  &[class*='_lef_'] {
    &[class*='_def'] {
      div[class='text'] {
        grid-area: 2 / 3 / 3 / 6; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
      div[class='icon'] {
        grid-area: 2 / 2 / 3 / 3; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
      div[class='back'] {
        grid-area: 2 / 1 / 3 / 6; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
    }
    &[class*='_alt'] {
      div[class='text'],
      div[class='icon'],
      div[class='back'] {
        grid-area: 2 / 1 / 3 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
    }
  }
  &[class*='_rig_'] {
    &[class*='_def'] {
      div[class='text'] {
        grid-area: 2 / 2 / 3 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
      div[class='icon'] {
        grid-area: 2 / 5 / 3 / 6; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
      div[class='back'] {
        grid-area: 2 / 2 / 3 / 7; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
    }
    &[class*='_alt'] {
      div[class='text'],
      div[class='icon'],
      div[class='back'] {
        grid-area: 2 / 2 / 3 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
    }
  }
  &[class*='_cen_'] {
    div[class='text'] {
      grid-area: 2 / 2 / 3 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
    div[class='icon'] {
      grid-area: 2 / 3 / 3 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
    div[class='back'] {
      grid-area: 2 / 2 / 3 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
  }
  &[class*='_tex_'] {
    div[class='text'],
    div[class='back'] {
      grid-area: 2 / 2 / 3 / 3; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
  }
  &[class*='_ico_'] {
    div[class='icon'],
    div[class='back'] {
      grid-area: 2 / 2 / 3 / 3; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
  }
}
