//--|🠊 Division.fullscreen.scss 🠈|--\\
@mixin desktop-landscape {
  //--|🠋 Desktop: Fullscreen Fade 🠋|--\\
  //--|🠊 Half the grid: one row (top & bottom) and half a column (left & right) 🠈|--\\
  mask-image: //--|🠋 Width: 1920px 🠋|--\\
    linear-gradient(to bottom, transparent 0rem, black 4rem, black calc(100% - 4rem), transparent 100%),
    linear-gradient(to right, transparent 0px, black 24px, black calc(100% - 24px), transparent 100%);
  mask-composite: intersect; //--|🠈 Both fades at once 🠈|--\\
  @media screen and (max-height: 768px) {
    mask-image: //--|🠋 Width: 1366px 🠋|--\\
      linear-gradient(to bottom, transparent 0rem, black 3rem, black calc(100% - 3rem), transparent 100%),
      linear-gradient(to right, transparent 0px, black 16px, black calc(100% - 16px), transparent 100%);
  }
  @media screen and (max-height: 480px) {
    mask-image: //--|🠋 Width: 854px 🠋|--\\
      linear-gradient(to bottom, transparent 0rem, black 2rem, black calc(100% - 2rem), transparent 100%),
      linear-gradient(to right, transparent 0px, black 12px, black calc(100% - 12px), transparent 100%);
  }
  @media screen and (max-height: 360px) {
    mask-image: //--|🠋 Width: 640px 🠋|--\\
      linear-gradient(to bottom, transparent 0rem, black 1.5rem, black calc(100% - 1.5rem), transparent 100%),
      linear-gradient(to right, transparent 0px, black 8px, black calc(100% - 8px), transparent 100%);
  }
  //--|🠊 Outer only: a nested fullscreen never fades, so its children stay untouched 🠈|--\\
  div[class*='fullscreen'] {
    mask-image: none;
  }
  //--|🠋 Slides (Desktop) 🠋|--\\
  %hori-scope-desk {
    //--|🠊 <ul class="hori-X-axis"> 🠈|--\\
    li[class*='horizontal'] {
      transition: transform 500ms ease-in-out;
      > div[class*='container'] {
        //--|🠊 Own container only, never a nested fullscreen 🠈|--\\
        display: flex;
        flex-direction: row; //--|🠈 flexbox: slides side by side 🠈|--\\
        grid-auto-flow: column; //--|🠈 gridbox: slides side by side 🠈|--\\
        grid-auto-columns: 100%; //--|🠈 gridbox: one slide per view 🠈|--\\
        > * {
          height: 100svh; //--|🠈 One slide per view 🠈|--\\
        }
      }
    }
  }
  %hori-stack-desk {
    li[class*='fullscreen'] {
      &[class*='horizontal_O'] {
        //--|🠊 Zero means nothing shows: sits on I, hidden and untouchable 🠈|--\\
        transform: translateX(0);
        opacity: 0;
        pointer-events: none;
      }
      &[class*='horizontal_I'] {
        transform: translateX(0);
      }
      &[class*='horizontal_II'] {
        transform: translateX(-100%);
      }
      &[class*='horizontal_III'] {
        transform: translateX(-200%);
      }
      &[class*='horizontal_IV'] {
        transform: translateX(-300%);
      }
      &[class*='horizontal_V'] {
        transform: translateX(-400%);
      }
      &[class*='horizontal_VI'] {
        transform: translateX(-500%);
      }
      &[class*='horizontal_VII'] {
        transform: translateX(-600%);
      }
      &[class*='horizontal_VIII'] {
        transform: translateX(-700%);
      }
      &[class*='horizontal_IX'] {
        transform: translateX(-800%);
      }
      &[class*='horizontal_X'] {
        transform: translateX(-900%);
      }
      &[class*='horizontal_XI'] {
        transform: translateX(-1000%);
      }
      &[class*='horizontal_XII'] {
        transform: translateX(-1100%);
      }
      &[class*='horizontal_XIII'] {
        transform: translateX(-1200%);
      }
      &[class*='horizontal_XIV'] {
        transform: translateX(-1300%);
      }
      &[class*='horizontal_XV'] {
        transform: translateX(-1400%);
      }
      &[class*='horizontal_XVI'] {
        transform: translateX(-1500%);
      }
      &[class*='horizontal_XVII'] {
        transform: translateX(-1600%);
      }
      &[class*='horizontal_XVIII'] {
        transform: translateX(-1700%);
      }
      &[class*='horizontal_XIX'] {
        transform: translateX(-1800%);
      }
      &[class*='horizontal_XX'] {
        transform: translateX(-1900%);
      }
    }
  }
  %vert-scope-desk {
    //--|🠊 <ol class="vert-Y-axis"> 🠈|--\\
    height: 100%;
    display: flex;
    li[class*='vertical'] {
      width: 100%;
      transition: transform 500ms ease-in-out;
      > div[class*='container'] {
        //--|🠊 Own container only, never a nested fullscreen 🠈|--\\
        display: flex;
        flex-direction: column; //--|🠈 flexbox: slides stacked 🠈|--\\
        grid-auto-flow: row; //--|🠈 gridbox: slides stacked 🠈|--\\
        > * {
          height: 100svh; //--|🠈 One slide per view, matching the translateY(-100svh) steps 🠈|--\\
        }
      }
    }
  }
  %vert-stack-desk {
    li[class*='fullscreen'] {
      &[class*='vertical_O'] {
        //--|🠊 Zero means nothing shows: sits on I, hidden and untouchable 🠈|--\\
        transform: translateY(0);
        opacity: 0;
        pointer-events: none;
      }
      &[class*='vertical_I'] {
        transform: translateY(0);
      }
      &[class*='vertical_II'] {
        transform: translateY(-100svh);
      }
      &[class*='vertical_III'] {
        transform: translateY(-200svh);
      }
      &[class*='vertical_IV'] {
        transform: translateY(-300svh);
      }
      &[class*='vertical_V'] {
        transform: translateY(-400svh);
      }
      &[class*='vertical_VI'] {
        transform: translateY(-500svh);
      }
      &[class*='vertical_VII'] {
        transform: translateY(-600svh);
      }
      &[class*='vertical_VIII'] {
        transform: translateY(-700svh);
      }
      &[class*='vertical_IX'] {
        transform: translateY(-800svh);
      }
      &[class*='vertical_X'] {
        transform: translateY(-900svh);
      }
      &[class*='vertical_XI'] {
        transform: translateY(-1000svh);
      }
      &[class*='vertical_XII'] {
        transform: translateY(-1100svh);
      }
      &[class*='vertical_XIII'] {
        transform: translateY(-1200svh);
      }
      &[class*='vertical_XIV'] {
        transform: translateY(-1300svh);
      }
      &[class*='vertical_XV'] {
        transform: translateY(-1400svh);
      }
      &[class*='vertical_XVI'] {
        transform: translateY(-1500svh);
      }
      &[class*='vertical_XVII'] {
        transform: translateY(-1600svh);
      }
      &[class*='vertical_XVIII'] {
        transform: translateY(-1700svh);
      }
      &[class*='vertical_XIX'] {
        transform: translateY(-1800svh);
      }
      &[class*='vertical_XX'] {
        transform: translateY(-1900svh);
      }
    }
  }
  ul[class='hori-X-axis'] {
    @extend %hori-scope-desk;
    @extend %hori-stack-desk;
  }
  ol[class='vert-Y-axis'] {
    @extend %vert-stack-desk;
    @extend %vert-scope-desk;
  }
}
