@mixin tablet-squaring {
  //--|🠋 Tablet: Fullscreen Fade 🠋|--\\
  //--|🠊 Only the fade scales on tablet, one step ahead of the grid 🠈|--\\
  @media screen and (orientation: landscape) {
    //--|🠊 Desktop 🠈|--\\
    //--|🠊 Outer only: a nested fullscreen never fades, so its children stay untouched 🠈|--\\
    div[class*='fullscreen'] {
      mask-image: none;
    }
    mask-composite: intersect; //--|🠈 Both fades at once 🠈|--\\
    mask-image: //--|🠋 Width: 1920px 🠋|--\\
      linear-gradient(to bottom, transparent 0rem, black 4rem, black calc(100% - 4rem), transparent 100%),
      linear-gradient(to right, transparent 0px, black 24px, black calc(100% - 24px), transparent 100%);
    @media screen and (max-width: 1920px) {
      mask-image: //--|🠋 Width: 1366px 🠋|--\\
        linear-gradient(to bottom, transparent 0rem, black 3rem, black calc(100% - 3rem), transparent 100%),
        linear-gradient(to right, transparent 0px, black 16px, black calc(100% - 16px), transparent 100%);
    }
    @media screen and (max-width: 1366px) {
      mask-image: //--|🠋 Width: 854px 🠋|--\\
        linear-gradient(to bottom, transparent 0rem, black 2rem, black calc(100% - 2rem), transparent 100%),
        linear-gradient(to right, transparent 0px, black 12px, black calc(100% - 12px), transparent 100%);
    }
    @media screen and (max-width: 854px) {
      mask-image: //--|🠋 Width: 640px 🠋|--\\
        linear-gradient(to bottom, transparent 0rem, black 1.5rem, black calc(100% - 1.5rem), transparent 100%),
        linear-gradient(to right, transparent 0px, black 8px, black calc(100% - 8px), transparent 100%);
    }
  }
  @media screen and (orientation: portrait) {
    //--|🠊 Mobile 🠈|--\\
    //--|🠊 Outer only: a nested fullscreen never fades, so its children stay untouched 🠈|--\\
    div[class*='fullscreen'] {
      mask-image: none;
    }
    mask-composite: intersect; //--|🠈 Both fades at once 🠈|--\\
    mask-image: //--|🠋 Height: 1920px 🠋|--\\
      linear-gradient(to bottom, transparent 0rem, black 6rem, black calc(100% - 6rem), transparent 100%),
      linear-gradient(to right, transparent 0px, black 32px, black calc(100% - 32px), transparent 100%);
    @media screen and (max-height: 1920px) {
      mask-image: //--|🠋 Height: 1366px 🠋|--\\
        linear-gradient(to bottom, transparent 0rem, black 5rem, black calc(100% - 5rem), transparent 100%),
        linear-gradient(to right, transparent 0px, black 24px, black calc(100% - 24px), transparent 100%);
    }
    @media screen and (max-height: 1366px) {
      mask-image: //--|🠋 Height: 854px 🠋|--\\
        linear-gradient(to bottom, transparent 0rem, black 3rem, black calc(100% - 3rem), transparent 100%),
        linear-gradient(to right, transparent 0px, black 16px, black calc(100% - 16px), transparent 100%);
    }
    @media screen and (max-height: 854px) {
      mask-image: //--|🠋 Height: 640px 🠋|--\\
        linear-gradient(to bottom, transparent 0rem, black 2rem, black calc(100% - 2rem), transparent 100%),
        linear-gradient(to right, transparent 0px, black 12px, black calc(100% - 12px), transparent 100%);
    }
  }
}

div[class*='fullscreen'] {
  //--|🠋 Desktop (Landscape) 🠋|--\\
  @media screen and (orientation: landscape) {
    @include desktop-landscape();
  }
  //--|🠋 Mobile (Portrait) 🠋|--\\
  @media screen and (orientation: portrait) {
    @include mobile-portrait();
  }
  //--|🠋 Tablet (Squaring) 🠋|--\\
  @media screen and (max-aspect-ratio: 15.99/9) and (min-aspect-ratio: 9/15.99) {
    @include tablet-squaring();
  }
}
