//--|🠊 RoutingButton.scss 🠈|--\\
@use '../../../../../../styles/Utilities.scss' as Utilities;
@mixin desktop-landscape {
  //--|🠊 <aside className="routing-button"> 🠈|--\\
  $high-desk: 128px; //--|🠈 128px for Squares 🠈|--\\
  $test-desk: 96px; //--|🠈 96px for Squares 🠈|--\\
  $misc-desk: 64px; //--|🠈 64px for Squares 🠈|--\\
  $tiny-desk: 48px; //--|🠈 48px for Squares 🠈|--\\
  overflow-y: hidden;
  section[class*='main-fore'] {
    display: grid;
    $high-desk: 128px; //--|🠈 128px for Squares 🠈|--\\
    $test-desk: 96px; //--|🠈 96px for Squares 🠈|--\\
    $misc-desk: 64px; //--|🠈 64px for Squares 🠈|--\\
    $tiny-desk: 48px; //--|🠈 48px for Squares 🠈|--\\

    div[class*='colourize'] {
      &.downplay {
        @include Utilities.downplay();
      }
      z-index: 2;
      display: flex; //--|🠈 Division.colourize.scss sets the direction 🠈|--\\
      grid-area: 2 / 3 / 5 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\

      margin: $high-desk 0; //--|🠈 96px (Left & Right) for Design 🠈|--\\
      @media screen and (max-height: 768px) {
        margin: $test-desk 0; //--|🠈 64px (Left & Right) for Design 🠈|--\\
      }
      @media screen and (max-height: 480px) {
        margin: $misc-desk 0; //--|🠈 48px (Left & Right) for Design 🠈|--\\
      }
      @media screen and (max-height: 360px) {
        margin: $tiny-desk 0; //--|🠈 32px (Left & Right) for Design 🠈|--\\
      }
    }
    div[class*='fullscreen'] {
      z-index: 0;

      div[class*='container'] {
        display: list-item;
        section[class*='one'] {
          //--|🠊 background: rgba(darkgreen, 0.25); 🠈|--\\

          grid-template: 1fr repeat(3, auto) 1fr //--|🠈 rows 🠈|--//
            / 1fr repeat(3, auto) 1fr; //--|🠈 columns 🠈|--\\

          /*
            $high-one: 128px;
            $test-one: 96px;
            $misc-one: 64px;
            $tiny-one: 48px;
  
            grid-template: //--|🠋 Width: 1920px 🠋|--\\
              1fr repeat(3, $high-one) 1fr //--|🠈 rows 🠈|--//
              / 1fr repeat(3, $high-one) 1fr; //--|🠈 columns 🠈|--\\
            @media screen and (max-height: 768px) {
              grid-template: //--|🠋 Width: 1366px 🠋|--\\
                1fr repeat(3, $test-one) 1fr //--|🠈 rows 🠈|--//
                / 1fr repeat(3, $test-one) 1fr; //--|🠈 columns 🠈|--\\
            }
            @media screen and (max-height: 480px) {
              grid-template: //--|🠋 Width: 854px 🠋|--\\
                1fr repeat(3, $misc-one) 1fr //--|🠈 rows 🠈|--//
                / 1fr repeat(3, $misc-one) 1fr; //--|🠈 columns 🠈|--\\
            }
            @media screen and (max-height: 360px) {
              grid-template: //--|🠋 Width: 640px 🠋|--\\
                1fr repeat(3, $tiny-one) 1fr //--|🠈 rows 🠈|--//
                / 1fr repeat(3, $tiny-one) 1fr; //--|🠈 columns 🠈|--\\
            }
          */
        }
        section[class*='fou'] {
          //--|🠊 background: rgba(darkblue, 0.25); 🠈|--\\

          grid-template: //--|🠋 Width: 1920px 🠋|--\\
            1fr repeat(3, auto) 1fr //--|🠈 rows 🠈|--//
            / 1fr repeat(3, auto) 1fr; //--|🠈 columns 🠈|--\\
          /*
            $high-fou: 84px;
            $test-fou: 64px;
            $misc-fou: 42px;
            $tiny-fou: 32px;
            grid-template: //--|🠋 Width: 1920px 🠋|--\\
              1fr repeat(3, $high-one) 1fr //--|🠈 rows 🠈|--//
              / 1fr repeat(3, $high-one) 1fr; //--|🠈 columns 🠈|--\\
            @media screen and (max-height: 768px) {
              grid-template: //--|🠋 Width: 1366px 🠋|--\\
                1fr repeat(3, $test-fou) 1fr //--|🠈 rows 🠈|--//
                / 1fr repeat(3, $test-fou) 1fr; //--|🠈 columns 🠈|--\\
            }
            @media screen and (max-height: 480px) {
              grid-template: //--|🠋 Width: 854px 🠋|--\\
                1fr repeat(3, $misc-fou) 1fr //--|🠈 rows 🠈|--//
                / 1fr repeat(3, $misc-fou) 1fr; //--|🠈 columns 🠈|--\\
            }
            @media screen and (max-height: 360px) {
              grid-template: //--|🠋 Width: 640px 🠋|--\\
                1fr repeat(3, $tiny-fou) 1fr //--|🠈 rows 🠈|--//
                / 1fr repeat(3, $tiny-fou) 1fr; //--|🠈 columns 🠈|--\\
            }
          */
