        section[class*='par'] {
          //--|🠊 background: rgba(darkred, 0.25); 🠈|--\\

          grid-template: //--|🠋 Width: 1920px 🠋|--\\
            1fr repeat(3, auto) 1fr //--|🠈 rows 🠈|--//
