            $high-par: 64px;
            $test-par: 48px;
            $misc-par: 32px;
            $tiny-par: 24px;
            grid-template: //--|🠋 Width: 1920px 🠋|--\\
              1fr repeat(3, $high-one) 1fr //--|🠈 rows 🠈|--//
              / 1fr repeat(3, $high-one) 1fr; //--|🠈 columns 🠈|--\\
            @media screen and (max-height: 768px) {
              grid-template: //--|🠋 Width: 1366px 🠋|--\\
                1fr repeat(3, $test-par) 1fr //--|🠈 rows 🠈|--//
                / 1fr repeat(3, $test-par) 1fr; //--|🠈 columns 🠈|--\\
            }
            @media screen and (max-height: 480px) {
              grid-template: //--|🠋 Width: 854px 🠋|--\\
                1fr repeat(3, $misc-par) 1fr //--|🠈 rows 🠈|--//
                / 1fr repeat(3, $misc-par) 1fr; //--|🠈 columns 🠈|--\\
            }
            @media screen and (max-height: 360px) {
              grid-template: //--|🠋 Width: 640px 🠋|--\\
                1fr repeat(3, $tiny-par) 1fr //--|🠈 rows 🠈|--//
                / 1fr repeat(3, $tiny-par) 1fr; //--|🠈 columns 🠈|--\\
            }
          */
        }
        section[class*='routing'] {
          display: grid;

          button[class*='_tl_'] {
            grid-area: 2 / 2 / 3 / 3; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          button[class*='_tc_'] {
            grid-area: 2 / 3 / 3 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          button[class*='_tr_'] {
            grid-area: 2 / 4 / 3 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          button[class*='_ml_'] {
            grid-area: 3 / 2 / 4 / 3; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          button[class*='_mc_'] {
            grid-area: 3 / 3 / 4 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          button[class*='_mr_'] {
            grid-area: 3 / 4 / 4 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          button[class*='_bl_'] {
            grid-area: 4 / 2 / 5 / 3; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          button[class*='_bc_'] {
            grid-area: 4 / 3 / 5 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          button[class*='_br_'] {
            grid-area: 4 / 4 / 5 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }

