        //--|🠊 background: black; 🠈|--\\
        grid-area: 1 / 1 / 6 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
      &[class*='lightside'] {
        //--|🠊 background: white; 🠈|--\\
        grid-area: 1 / 4 / 6 / 7; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
    }
    menu[class*='routing'] {
      z-index: 1;
      &[class*='darkside'] {
        grid-area: 2 / 3 / 5 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
      &[class*='lightside'] {
        grid-area: 2 / 4 / 5 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
    }
    fieldset {
      display: flex;
      align-items: center;
      justify-content: space-around;
      &[class*='darkside'] {
        grid-area: 4 / 1 / 6 / 7; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
      &[class*='lightside'] {
        margin-left: auto;
        grid-area: 1 / 1 / 2 / 7; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }

      height: $high-desk;
      width: calc($high-desk * 2);
      @media screen and (max-height: 768px) {
        height: $test-desk;
        width: calc($test-desk * 2);
      }
      @media screen and (max-height: 480px) {
        height: $misc-desk;
        width: calc($misc-desk * 2);
      }
      @media screen and (max-height: 360px) {
        height: $tiny-desk;
        width: calc($tiny-desk * 2);
      }
    }

    //--|🠋 96px (Left & Right) for Design 🠋|--\\
    grid-template: //--|🠋 Width: 1920px 🠋|--\\
      repeat(2, 4rem) 1fr repeat(2, 4rem) //--|🠈 rows 🠈|--//
      / 48px 1fr repeat(2, $high-desk) 1fr 48px; //--|🠈 columns 🠈|--\\
    @media screen and (max-height: 768px) {
      //--|🠋 64px (Left & Right) for Design 🠋|--\\
      grid-template: //--|🠋 Width: 1366px 🠋|--\\
        repeat(2, 3rem) 1fr repeat(2, 3rem) //--|🠈 rows 🠈|--//
        / 32px 1fr repeat(2, $test-desk) 1fr 32px; //--|🠈 columns 🠈|--\\
    }
    @media screen and (max-height: 480px) {
      //--|🠋 48px (Left & Right) for Design 🠋|--\\
      grid-template: //--|🠋 Width: 854px 🠋|--\\
        repeat(2, 2rem) 1fr repeat(2, 2rem) //--|🠈 rows 🠈|--//
        / 24px 1fr repeat(2, $misc-desk) 1fr 24px; //--|🠈 columns 🠈|--\\
    }
    @media screen and (max-height: 360px) {
      //--|🠋 32px (Left & Right) for Design 🠋|--\\
      grid-template: //--|🠋 Width: 640px 🠋|--\\
        repeat(2, 1.5rem) 1fr repeat(2, 1.5rem) //--|🠈 rows 🠈|--//
        / 16px 1fr repeat(2, $tiny-desk) 1fr 16px; //--|🠈 columns 🠈|--\\
    }
  }
  figure[class*='main-mid'] {
  }
  div[class*='main-back'] {
  }
}
