                //--|🠊 32px (Left & Right) for Design 🠈|--\\
                grid-template: //--|🠋 Height: 854px 🠋|--\\
                  6rem 1fr repeat(3, auto) 6rem //--|🠈 rows 🠈|--//
                  / 32px 1fr repeat(3, auto) 1fr 32px; //--|🠈 columns 🠈|--\\
              }
              @media screen and (max-width: 360px) {
                //--|🠊 24px (Left & Right) for Design 🠈|--\\
                grid-template: //--|🠋 Height: 640px 🠋|--\\
                  4rem 1fr repeat(3, auto) 4rem //--|🠈 rows 🠈|--//
                  / 24px 1fr repeat(3, auto) 1fr 24px; //--|🠈 columns 🠈|--\\
              }
            }
            &[class*='par'] {
              //--|🠊 background: rgba(darkred, 0.25); 🠈|--\\

              //--|🠊 64px (Left & Right) for Design 🠈|--\\
              grid-template: //--|🠋 Height: 1920px 🠋|--\\
                12rem 1fr repeat(3, auto) 12rem //--|🠈 rows 🠈|--//
                / 64px 1fr repeat(3, auto) 1fr 64px; //--|🠈 columns 🠈|--\\
              @media screen and (max-width: 768px) {
                //--|🠊 48px (Left & Right) for Design 🠈|--\\
                grid-template: //--|🠋 Height: 1366px 🠋|--\\
                  10rem 1fr repeat(3, auto) 10rem //--|🠈 rows 🠈|--//
                  / 48px 1fr repeat(3, auto) 1fr 48px; //--|🠈 columns 🠈|--\\
              }
              @media screen and (max-width: 480px) {
                //--|🠊 32px (Left & Right) for Design 🠈|--\\
                grid-template: //--|🠋 Height: 854px 🠋|--\\
                  6rem 1fr repeat(3, auto) 6rem //--|🠈 rows 🠈|--//
                  / 32px 1fr repeat(3, auto) 1fr 32px; //--|🠈 columns 🠈|--\\
              }
              @media screen and (max-width: 360px) {
                //--|🠊 24px (Left & Right) for Design 🠈|--\\
                grid-template: //--|🠋 Height: 640px 🠋|--\\
                  4rem 1fr repeat(3, auto) 4rem //--|🠈 rows 🠈|--//
                  / 24px 1fr repeat(3, auto) 1fr 24px; //--|🠈 columns 🠈|--\\
              }
            }
          }

          grid-gap: 16px;
          @media screen and (max-width: 768px) {
            grid-gap: 12px;
          }
          @media screen and (max-width: 480px) {
            grid-gap: 6px;
          }
          @media screen and (max-width: 360px) {
            grid-gap: 4px;
          }
        }
      }
    }
    fieldset {
      display: flex;
      align-items: center;
      justify-content: space-around;
      &[class*='darkside'] {
        margin-left: auto;
        grid-area: 1 / 1 / 2 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
      &[class*='lightside'] {
        margin-right: auto;
        grid-area: 6 / 1 / 8 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }

      width: $high-mobi;
      height: $high-mobi;
      @media screen and (max-width: 768px) {
        width: $test-mobi;
        height: $test-mobi;
      }
      @media screen and (max-width: 480px) {
        width: $misc-mobi;
        height: $misc-mobi;
      }
      @media screen and (max-width: 360px) {
        width: $tiny-mobi;
        height: $tiny-mobi;
      }
    }

    //--|🠊 64px (Left & Right) for Design 🠈|--\\
    grid-template: //--|🠋 Height: 1920px 🠋|--\\
      repeat(2, 6rem) 1fr 12rem 1fr repeat(2, 6rem) //--|🠈 rows 🠈|--//
      / 64px 1fr 64px; //--|🠈 columns 🠈|--\\
    menu {
      padding: 0 128px;
    }
    @media screen and (max-width: 768px) {
      //--|🠊 48px (Left & Right) for Design 🠈|--\\
      grid-template: //--|🠋 Height: 1366px 🠋|--\\
        repeat(2, 5rem) 1fr 10rem 1fr repeat(2, 5rem) //--|🠈 rows 🠈|--//
        / 48px 1fr 48px; //--|🠈 columns 🠈|--\\
      menu {
        padding: 0 112px;
      }
    }
    @media screen and (max-width: 480px) {
      //--|🠊 32px (Left & Right) for Design 🠈|--\\
      grid-template: //--|🠋 Height: 854px 🠋|--\\
        repeat(2, 3rem) 1fr 6rem 1fr repeat(2, 3rem) //--|🠈 rows 🠈|--//
        / 32px 1fr 32px; //--|🠈 columns 🠈|--\\
      menu {
        padding: 0 64px;
      }
    }
    @media screen and (max-width: 360px) {
      //--|🠊 24px (Left & Right) for Design 🠈|--\\
      grid-template: //--|🠋 Height: 640px 🠋|--\\
        repeat(2, 2rem) 1fr 4rem 1fr repeat(2, 2rem) //--|🠈 rows 🠈|--//
        / 24px 1fr 24px; //--|🠈 columns 🠈|--\\
      menu {
        padding: 0 40px;
      }
    }
  }
