  //--|===|--\\
  %mark-area-mobi {
    menu,
    fieldset {
      z-index: 2;
      &[class*='darkside'] {
        grid-area: 1 / 2 / 3 / 3; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
      &[class*='lightside'] {
        grid-area: 6 / 2 / 8 / 3; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
    }
    div[class*='colourize'] {
      &.downplay {
        @include Utilities.downplay();
      }
      z-index: 1;
      grid-area: 4 / 2 / 5 / 3; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
    div[class*='fullscreen'] {
      z-index: 0;
      overflow: hidden;
      grid-area: 1 / 1 / 8 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      &[class*='darkside'] {
        //--|🠊 background: rgba(black, 0.25); 🠈|--\\
        clip-path: inset(0 0 50% 0); //--|🠈 top / right / bottom / left 🠈|--\\
      }
      &[class*='lightside'] {
        //--|🠊 background: rgba(white, 0.25); 🠈|--\\
        clip-path: inset(50% 0 0 0); //--|🠈 top / right / bottom / left 🠈|--\\
      }
    }
  }
  %mark-disp-mobi {
    display: grid;
    div[class*='fullscreen'] {
      //--|🠊 display: flex; 🠈|--\\
      &[class*='side-main'] {
        flex-direction: column;
      }
      div[class*='container'] {
        &[class*='side-main'] {
          flex-direction: column;
        }
        section[class*='routing-main'] {
          display: grid;
          height: 100svh;
        }
      }
    }
    div[class*='colourize'] {
      &.downplay {
        @include Utilities.downplay();
      }
      display: flex; //--|🠈 Division.colourize.scss sets the direction 🠈|--\\
    }
  }
}
