//--|🠊 Aside.characters.scss 🠈|--\\
@use '../../../styles/Palettes.scss' as Palettes;

@mixin desktop-landscape {
  //--|🠋 Desktop (Characters) 🠋|--\\
  %desk-flex {
    //--|🠊 Style View 🠈|--\\
    @at-root aside[class*='characters-default'] {
      &[class*='lef_'] {
        margin-right: auto;
      }
      &[class*='rig_'] {
        margin-left: auto;
      }
      div[class='characters'] {
        margin: 0 48px; //--|🠈 48px × 2 = 96px (Left & Right) for Design 🠈|--\\
        @media screen and (max-height: 768px) {
          margin: 0 32px; //--|🠈 32px × 2 = 64px (Left & Right) for Design 🠈|--\\
        }
        @media screen and (max-height: 480px) {
          margin: 0 24px; //--|🠈 24px × 2 = 48px (Left & Right) for Design 🠈|--\\
        }
        @media screen and (max-height: 360px) {
          margin: 0 16px; //--|🠈 16px × 2 = 32px (Left & Right) for Design 🠈|--\\
        }
      }
    }
  }
  %desk-grid {
    @at-root aside[class*='characters-default'] {
      div[class='characters'] {
        display: inherit; //--|🠈 display: grid; 🠈|--\\
        grid-area: 2 / 1 / 3 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
        grid-template: repeat(4, auto) 1fr //--|🠈 rows 🠈|--\\
          / repeat(3, auto); //--|🠈 columns 🠈|--\\
        button {
          padding-top: 4px;
          padding-bottom: 4px;
          &:nth-child(1) {
            grid-area: 1 / 1 / 2 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          &:nth-child(2) {
            grid-area: 2 / 1 / 3 / 2; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          &:nth-child(3) {
            grid-area: 2 / 2 / 3 / 3; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          &:nth-child(4) {
            grid-area: 2 / 3 / 3 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          &:nth-child(5) {
            grid-area: 3 / 1 / 4 / 2; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          &:nth-child(6) {
            grid-area: 3 / 2 / 4 / 3; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          &:nth-child(7) {
            grid-area: 3 / 3 / 4 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          &:nth-child(8) {
            grid-area: 4 / 1 / 5 / 2; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
          &:nth-child(9) {
            grid-area: 4 / 3 / 5 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
        }
      }
      //--|===|--\\
      width: 398px; //--|🠊 96px for Left & Right 🠈|--\\
      grid-template: //--|🠋 Width: 1920px 🠋|--\\
        64px auto 1fr 64px //--|🠈 rows 🠈|--\\
        / 48px 1fr 48px; //--|🠈 columns 🠈|--\\
      @media screen and (max-height: 768px) {
        width: 321px; //--|🠊 64px for Left & Right 🠈|--\\
        grid-template: //--|🠋 Width: 1366px 🠋|--\\
          48px auto 1fr 48px //--|🠈 rows 🠈|--\\
          / 32px 1fr 32px; //--|🠈 columns 🠈|--\\
      }
      @media screen and (max-height: 480px) {
        width: 230px; //--|🠊 48px for Left & Right 🠈|--\\
        grid-template: //--|🠋 Width: 854px 🠋|--\\
          32px auto 1fr 32px //--|🠈 rows 🠈|--\\
          / 24px 1fr 24px; //--|🠈 columns 🠈|--\\
      }
      @media screen and (max-height: 360px) {
        width: 139px; //--|🠊 32px for Left & Right 🠈|--\\
        grid-template: //--|🠋 Width: 640px 🠋|--\\
          24px 1fr auto 1fr 24px //--|🠈 rows 🠈|--\\
          / 16px 1fr 16px; //--|🠈 columns 🠈|--\\
      }
    }
  }
  %desk-tint {
    //--|🠊 Style Color & Shade 🠈|--\\
    @at-root aside[class*='characters-default'] {
      &[class*='_dar_'] {
        &[class*='_mon'] {
          background: Palettes.$gray-darkMode;
        }
        &[class*='_red'] {
          background: Palettes.$red-darkMode;
        }
        &[class*='_gre'] {
          background: Palettes.$green-darkMode;
        }
        &[class*='_blu'] {
          background: Palettes.$blue-darkMode;
        }
        &[class*='_pur'] {
          background: Palettes.$purple-darkMode;
        }
        &[class*='_ora'] {
          background: Palettes.$orange-darkMode;
        }
        &[class*='_pin'] {
          background: Palettes.$pink-darkMode;
        }
        &[class*='_yel'] {
          background: Palettes.$yellow-darkMode;
        }
        &[class*='_bro'] {
          background: Palettes.$brown-darkMode;
        }
        &[class*='_tur'] {
          background: Palettes.$turquoise-darkMode;
        }
        //--|🠊 AI Code: Review Please 2026-10-31 12:27 🠈|--\\
        &[class*='_opa'] {
          background: transparent; //--|🠈 ⟨opaque⟩ sets the background to 0 opacity 🠈|--\\
        }
      }
      &[class*='_lig_'] {
        &[class*='_mon'] {
          background: Palettes.$gray-lightMode;
        }
        &[class*='_red'] {
          background: Palettes.$red-lightMode;
        }
        &[class*='_gre'] {
          background: Palettes.$green-lightMode;
        }
        &[class*='_blu'] {
          background: Palettes.$blue-lightMode;
        }
        &[class*='_pur'] {
          background: Palettes.$purple-lightMode;
        }
        &[class*='_ora'] {
          background: Palettes.$orange-lightMode;
        }
        &[class*='_pin'] {
          background: Palettes.$pink-lightMode;
        }
        &[class*='_yel'] {
          background: Palettes.$yellow-lightMode;
        }
        &[class*='_bro'] {
          background: Palettes.$brown-lightMode;
        }
        &[class*='_tur'] {
          background: Palettes.$turquoise-lightMode;
        }
        //--|🠊 AI Code: Review Please 2026-10-31 12:27 🠈|--\\
        &[class*='_opa'] {
          background: transparent; //--|🠈 ⟨opaque⟩ sets the background to 0 opacity 🠈|--\\
        }
      }
    }
  }
  //--|===|--\\
  @extend %desk-flex;
  @extend %desk-grid;
  @extend %desk-tint;
}
@mixin mobile-portrait {
