          }
          &:nth-child(9) {
            grid-area: 9 / 1 / 10 / 2; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
          }
        }
        mask-image: linear-gradient(to bottom, transparent 0rem, black 1rem, black calc(100% - 1rem), transparent 100%);
        //--|===|--\\
        overflow-y: auto;
        scrollbar-width: none; //--|🠈 Firefox 🠈|--\\
        -ms-overflow-style: none; //--|🠈 IE/Edge 🠈|--\\
        &::-webkit-scrollbar {
          display: none; //--|🠈 Chrome/Safari 🠈|--\\
        }
