@mixin default-flexbox {
  //--|🠋 Global (Flex) 🠋|--\\
  div[class='icon'] {
    display: flex;
    align-items: center;
    //--|🠊 justify-content: center; 🠈|--\\
  }
  &[class*='_alt'] {
    div[class='icon'] {
      display: none; //--|🠈 No image, no icon layer: its crossfade would stretch over the whole button 🠈|--\\
    }
  }
  div[class='text'],
  div[class='icon'],
  div[class='back'] {
    p,
    h6,
    h5,
    h4,
    h3,
    h2,
    h1,
    img {
      cursor: pointer;
    }
    canvas {
      display: none;
    }
    &[class='text'] {
      z-index: 3;
      background-size: 100% 100%;
      background-repeat: no-repeat;
    }
    &[class='icon'] {
      z-index: 2;
      background-size: 100% 100%;
      background-repeat: no-repeat;
    }
    &[class='back'] {
      z-index: 1;
      overflow: hidden;
    }
  }
}
