//--|🠊 ArchiveHeader.scss 🠈|--\\
@use '../../../styles/Utilities.scss' as Utilities;

@mixin desktop-landscape {
  //--|🠊 Desktop <Header> 🠈|--\\
  $high-desk: 128px; //--|🠈 128px for Squares 🠈|--\\
  $test-desk: 96px; //--|🠈 96px for Squares 🠈|--\\
  $misc-desk: 64px; //--|🠈 64px for Squares 🠈|--\\
  $tiny-desk: 48px; //--|🠈 48px for Squares 🠈|--\\

  section[class*='header-fore'] {
    div[class*='conveyor'] {
      z-index: 1;
      grid-area: 1 / 1 / 3 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\

      margin-left: 128px; //--|🠈 128px for Squares 🠈|--\\
      @media screen and (max-height: 768px) {
        margin-left: 96px; //--|🠈 96px for Squares 🠈|--\\
      }
      @media screen and (max-height: 480px) {
        margin-left: 64px; //--|🠈 64px for Squares 🠈|--\\
      }
      @media screen and (max-height: 360px) {
        margin-left: 48px; //--|🠈 48px for Squares 🠈|--\\
      }
    }
    nav[class*='navigation'] {
      z-index: 0;
    }
  }
  figure[class*='header-mid'] {
    display: inherit; //--|🠈 display: grid; 🠈|--\\
    grid-template: inherit;

    .top {
      height: 50%; //--|🠈 AI Code: Review Please 2026-11-10 · Half the row, same as Mobile 🠈|--\\
      grid-area: 1 / 1 / 2 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      background: Utilities.$indexLand-lightMode;
      opacity: 1;
      transition: opacity 250ms ease-in-out; //--|🠈 Fades out when squaring: AI Code: Review Please 2026-11-07 🠈|--\\
      position: relative; //--|🠈 AI Code: Review Please 2026-11-10 🠈|--\\
      &::after {
        //--|🠊 AI Code: Review Please 2026-11-10 · A soft shade below the strip: hides what slides under the title, gone by the end of the row 🠈|--\\
        content: '';
        position: absolute;
        top: 100%;
        left: 0;
        width: 100%;
        height: 150%; //--|🠈 AI Code: Review Please 2026-11-10 · The other half of the row, then a little past it 🠈|--\\
        //--|🠊 AI Code: Review Please 2026-11-10 · Eased: holds dark under the title, then lets go gently, no hard edge 🠈|--\\
        background: linear-gradient(
          to bottom,
          rgba(Utilities.$gray-dark, 0.95) 0%,
          rgba(Utilities.$gray-dark, 0.9) 30%,
          rgba(Utilities.$gray-dark, 0.7) 55%,
          rgba(Utilities.$gray-dark, 0.4) 75%,
          rgba(Utilities.$gray-dark, 0.15) 90%,
          rgba(Utilities.$gray-dark, 0) 100%
        );
        pointer-events: none; //--|🠈 Clicks still reach what's underneath 🠈|--\\
      }
    }
  }
  div[class*='header-back'] {
  }
}
@mixin mobile-portrait {
  //--|🠊 Mobile <Header> 🠈|--\\
  $high-mobi: 192px; //--|🠈 192px for Squares 🠈|--\\
  $test-mobi: 160px; //--|🠈 160px for Squares 🠈|--\\
  $misc-mobi: 96px; //--|🠈 96px for Squares 🠈|--\\
  $tiny-mobi: 64px; //--|🠈 64px for Squares 🠈|--\\

  section[class*='header-fore'] {
    menu[class*='select'] {
      grid-area: 1 / 1 / 3 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\

      margin-left: $high-mobi;
      @media screen and (max-width: 768px) {
        margin-left: $test-mobi;
      }
      @media screen and (max-width: 480px) {
        margin-left: $misc-mobi;
      }
      @media screen and (max-width: 360px) {
        margin-left: $tiny-mobi;
      }
    }
  }
  figure[class*='header-mid'] {
    display: inherit; //--|🠈 display: grid; 🠈|--\\
    grid-template: inherit;

    .top {
      height: 50%;
      grid-area: 1 / 1 / 2 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      background: Utilities.$indexLand-lightMode;
      opacity: 1;
      transition: opacity 250ms ease-in-out; //--|🠈 Fades out when squaring: AI Code: Review Please 2026-11-07 🠈|--\\
      position: relative; //--|🠈 AI Code: Review Please 2026-11-10 🠈|--\\
      &::after {
        //--|🠊 AI Code: Review Please 2026-11-10 · A soft shade below the strip: hides what slides under the title, gone by the end of the row 🠈|--\\
        content: '';
        position: absolute;
        top: 100%;
        left: 0;
        width: 100%;
        height: 150%; //--|🠈 AI Code: Review Please 2026-11-10 · The other half of the row, then a little past it 🠈|--\\
        //--|🠊 AI Code: Review Please 2026-11-10 · Eased: holds dark under the title, then lets go gently, no hard edge 🠈|--\\
        background: linear-gradient(
          to bottom,
          rgba(Utilities.$gray-dark, 0.95) 0%,
          rgba(Utilities.$gray-dark, 0.9) 30%,
          rgba(Utilities.$gray-dark, 0.7) 55%,
          rgba(Utilities.$gray-dark, 0.4) 75%,
          rgba(Utilities.$gray-dark, 0.15) 90%,
          rgba(Utilities.$gray-dark, 0) 100%
        );
        pointer-events: none; //--|🠈 Clicks still reach what's underneath 🠈|--\\
      }
    }
  }
  div[class*='header-back'] {
    /*
    header {
      grid-area: 1 / 1 / 2 / 4;
      background: rgba(green, 0.25);
      //--|🠊 background: Utilities.$indexLand-lightMode; 🠈|--\\
      //--|🠊 filter: drop-shadow(0 1.5rem 1.5rem rgba(Utilities.$indexLand-light, 0.75)); 🠈|--\\
    }
    */
  }
}
//--|===|--\\
header[id*='components'] {
  //--|🠋 Desktop (Landscape) 🠋|--\\
  @media screen and (orientation: landscape) {
    @include desktop-landscape();
    &[class*='squaring'] {
      //--|🠊 AI Code: Review Please 2026-11-07 · Same as [overtime]: the squared corner only shows the nav, so the .top strip fades out 🠈|--\\
      figure[class*='header-mid'] > .top {
        opacity: 0;
      }
    }
  }
  //--|🠋 Mobile (Portrait) 🠋|--\\
  @media screen and (orientation: portrait) {
    @include mobile-portrait();
    &[class*='squaring'] {
      //--|🠊 AI Code: Review Please 2026-11-07 · Same as [overtime]: the squared corner only shows the nav, so the .top strip fades out 🠈|--\\
      figure[class*='header-mid'] > .top {
        opacity: 0;
      }
    }
  }
}
