//--|🠊 Text rows are 2.1 × the font (1.2 line + 0.9 padding, the 3.00 ratio on <h3> at 854); -top-/-bot- gutters are half the text row (odd rows rounded up to even), so every card is an exact square 🠈|--\\
@mixin glowing-gridbox {
  //--|🠋 Global (Grid) 🠋|--\\
  width: 100%;
  height: 100%;
  display: grid;
  //--|🠊 Placement: Global, so [MobilePortrait] & [TabletSquaring] get it too (Lost in 3adc1ea1) 🠈|--\\
  &[class*='_top_'] {
    div[class='text'] {
      grid-area: 2 / 2 / 3 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
    div[class='back'] {
      grid-area: 2 / 2 / 4 / 5; //--|🠈 A square card over the text and the icon 🠈|--\\
    }
    div[class='icon'] {
      grid-area: 3 / 3 / 4 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
  }
  &[class*='_bot_'] {
    div[class='text'] {
      grid-area: 3 / 2 / 4 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
    div[class='back'] {
      grid-area: 2 / 2 / 4 / 5; //--|🠈 A square card over the text and the icon 🠈|--\\
    }
    div[class='icon'] {
      grid-area: 2 / 3 / 3 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
  }
  &[class*='_lef_'] {
    &[class*='_glo'] {
      div[class='text'] {
        grid-area: 2 / 3 / 3 / 6; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
      div[class='icon'] {
        grid-area: 2 / 2 / 3 / 3; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
      div[class='back'] {
        grid-area: 2 / 1 / 3 / 6; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
    }
    &[class*='_alt'] {
      div[class='text'],
      div[class='icon'],
      div[class='back'] {
        grid-area: 2 / 1 / 3 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
    }
  }
  &[class*='_rig_'] {
    &[class*='_glo'] {
      div[class='text'] {
        grid-area: 2 / 2 / 3 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
      div[class='icon'] {
        grid-area: 2 / 5 / 3 / 6; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
      div[class='back'] {
        grid-area: 2 / 2 / 3 / 7; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
    }
    &[class*='_alt'] {
      div[class='text'],
      div[class='icon'],
      div[class='back'] {
        grid-area: 2 / 2 / 3 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      }
    }
  }
  &[class*='_cen_'] {
    div[class='text'] {
      grid-area: 2 / 2 / 3 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
    div[class='icon'] {
      grid-area: 2 / 3 / 3 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
    div[class='back'] {
      grid-area: 2 / 2 / 3 / 5; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
  }
  &[class*='_tex_'] {
    div[class='text'],
    div[class='back'] {
      grid-area: 2 / 2 / 3 / 3; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
  }
  &[class*='_ico_'] {
    div[class='icon'],
    div[class='back'] {
      grid-area: 2 / 2 / 3 / 3; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
  }
}
