//--|🠊 Label.selection.scss 🠈|--\\
//--|🠊 AI Code: Review Please 2026-10-30 · {select}, {combo} & {number} in one <label>, split into a pipeline like <ButtonDefault> 🠈|--\\
@use './pipeline/Label_flex.scss' as Label_flex;
@use './pipeline/Label_size.scss' as Label_size;
@use './pipeline/Label_tint.scss' as Label_tint;

label[class*='_selection-'] {
  @include Label_flex.selection-flexbox();
  @include Label_tint.selection-colors();

  //--|🠋 Desktop (Landscape) 🠋|--\\
  @media screen and (orientation: landscape) {
    //--|🠊 <LabelSelection> for [DesktopLandscape] 🠈|--\\
    @include Label_size.desktop-size();
  }
  //--|🠋 Mobile (Portrait) 🠋|--\\
  @media screen and (orientation: portrait) {
    //--|🠊 <LabelSelection> for [MobilePortrait] 🠈|--\\
    @include Label_size.mobile-size();
  }
  //--|🠋 Tablet (Squaring) 🠋|--\\
  @media screen and (max-aspect-ratio: 15.99/9) and (min-aspect-ratio: 9/15.99) {
    //--|🠊 <LabelSelection> for [TabletSquaring] 🠈|--\\
    @include Label_size.tablet-size();
  }
}
